function groupInGroups(arr, size) {
  const result = [];
  let group = [];
  for (const item of arr) {
    group.push(item);
    if (group.length === size) {
      result.push(group);
      group = [];
    }
  }
  if (group.length) result.push(group);
  return result;
}
